<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class LkdYoungAnnouncement extends Model {protected $fillable=['university_id','representative_id','created_by','subject','detail','status','approved_by','sent_at','recipient_count','failure_reason']; protected $casts=['sent_at'=>'datetime']; public function university(){return $this->belongsTo(Universities::class);} public function creator(){return $this->belongsTo(User::class,'created_by');}}
